public protocol SteamSessionProtocol: AnyObject, Sendable {
    
    func achievements(appId: UInt32, language: String) async throws  -> [SteamAchievement]
    
    func archiveCloud(config: SteamCloudConfiguration) async throws 
    
    func cancelDownload() 
    
    func cloudAutocloudMetadata() async throws  -> String
    
    /**
     * Explicit diagnostic operation using this already-authenticated session.
     * It downloads a verified backup; no Cloud mutation or game launch occurs.
     */
    func cloudBackup(appId: UInt32, directory: String) async throws  -> String
    
    func cloudInterruptionProbe(appId: UInt32, directory: String) async throws  -> String
    
    /**
     * Returns only Cloud preferences and source revision, never roaming data.
     */
    func cloudPreferences(appId: UInt32) async throws  -> String
    
    func cloudSdkCandidates() async throws  -> String
    
    func cloudTransferProbe(appId: UInt32, directory: String) async throws  -> String
    
    func details(appId: UInt32, language: String) async throws  -> SteamGameDetails
    
    func download(appId: UInt32, platform: String, language: String, directory: String) async throws  -> SteamInstallation
    
    func downloadProgress()  -> GameTransfer?
    
    func games() async throws  -> [SteamGame]
    
    func launchPlan(appId: UInt32, platform: String, directory: String) async throws  -> SteamLaunchPlan
    
    /**
     * Suspends on the CM watch channel; no content-query mutex is held.
     */
    func nextFriends(afterRevision: UInt64) async  -> SteamFriendsSnapshot
    
    /**
     * Declared application platforms in batches; an empty platform list means unknown.
     */
    func platforms(appIds: [UInt32]) async throws  -> [SteamGamePlatforms]
    
    func profile() async throws  -> SteamProfile
    
    /**
     * Also wakes UniFFI futures, whose Swift wrappers do not cancel Rust awaits.
     */
    func shutdown() 
    
}
